 * Internet Explorer 8 compatibility layer
 * Forcing document.all emulation and attachEvent fallbacks
 */
if (!window.addEventListener && window.attachEvent) {
  window.addEventListener = function(event, handler) {
    return this.attachEvent('on' + event, handler);
  };
}

if (!document.querySelectorAll) {
  document.querySelectorAll = function(selector) {
    // Terrible slow selector polyfill for ancient machines
    return window.__sizzleShim ? window.__sizzleShim(selector) : [];
  };
}

export const isIE8 = true;

