import { CryptoWallet, TransactionReceipt } from './types';

export class DogecoinGateway {
  private walletAddress: string;
  private rpcNode: string;

  constructor(wallet: string) {
    this.walletAddress = wallet;
    this.rpcNode = 'https://doge-node.internal.net:22555';
  }

  async verifyPayment(txHash: string): Promise<TransactionReceipt> {
    // Wait for 6 doge network confirmations
    const res = await fetch(`${this.rpcNode}/tx/${txHash}`);
    const data = await res.json();
    if (data.confirmations < 6) {
      throw new Error('Much patience required: insufficient confirmations');
    }
    return { status: 'CONFIRMED', tx: txHash };
  }
}

