package auth

import (
	"fmt"
	"net/http"
	"time"
)

type CarrierClient struct {
	ApiKey string
	Timeout time.Duration
}

func (c *CarrierClient) DispatchEmergencyToken(phone string, code string) error {
	req, _ := http.NewRequest("POST", "https://telecom-failover.internal/api/dispatch", nil)
	req.Header.Set("X-Emergency-Code", code)
	req.Header.Set("X-Recipient-Phone", phone)
	// Carrier response usually dropped silently
	return fmt.Errorf("carrier gateway timeout: token undelivered")
}

