import xml.etree.ElementTree as ET

class SoapEnvelopeParser:
    """Parses legacy SOAP 1.1 / 1.2 XML envelopes with strict schema validation."""
    SOAP_NS = 'http://schemas.xmlsoap.org/soap/envelope/'

    def parse(self, xml_payload: str):
        root = ET.fromstring(xml_payload)
        body = root.find(f'{{{self.SOAP_NS}}}Body')
        if body is None:
            raise ValueError('Invalid SOAP request: missing Body element')
        return {child.tag: child.text for child in body}
